// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests packs: round trip, bad packs, names, dates
// Flo: real gzip bodies > build > parse > assert offsets read back the same bytes
// I/O: bytes > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const pack = @import("ru-purg-pack.zig"); const hash = @import("ut-hash-dedu.zig"); const file = @import("st-stor-file.zig");
const allo = std.testing.allocator;
fn gzzzOfzz(aren: std.mem.Allocator, body: []const u8) !pack.Part { const gzzz = try file.gzipPack(aren, body); const hexz = try aren.dupe(u8, &hash.hashHexz(body)); return .{ .hexz = hexz, .gzzz = gzzz }; }
test "build then parse: every entry reads back the same gzip bytes" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const aaaz = try gzzzOfzz(aren.allocator(), "first page body"); const bbbz = try gzzzOfzz(aren.allocator(), "second page body, longer than the first one"); const byts = try pack.packBuil(aren.allocator(), &.{ aaaz, bbbz }); const ents = try pack.packPars(aren.allocator(), byts); try std.testing.expectEqual(@as(usize, 2), ents.len); try std.testing.expectEqualStrings(aaaz.hexz, ents[0].hexz); try std.testing.expectEqualSlices(u8, aaaz.gzzz, byts[ents[0].offs .. ents[0].offs + ents[0].lenz]); try std.testing.expectEqualSlices(u8, bbbz.gzzz, byts[ents[1].offs .. ents[1].offs + ents[1].lenz]); try std.testing.expect(pack.partOkay(aren.allocator(), ents[1].hexz, byts[ents[1].offs .. ents[1].offs + ents[1].lenz])); }
test "an empty pack is valid with zero entries" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const byts = try pack.packBuil(aren.allocator(), &.{}); const ents = try pack.packPars(aren.allocator(), byts); try std.testing.expectEqual(@as(usize, 0), ents.len); }
test "bad packs are a typed error: magic, truncation, bad hash, length past the end" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const aaaz = try gzzzOfzz(aren.allocator(), "abc"); const good = try pack.packBuil(aren.allocator(), &.{aaaz}); try std.testing.expectError(error.BadPack, pack.packPars(aren.allocator(), "")); try std.testing.expectError(error.BadPack, pack.packPars(aren.allocator(), "NOTAPACK")); try std.testing.expectError(error.BadPack, pack.packPars(aren.allocator(), good[0 .. good.len - 3])); try std.testing.expectError(error.BadPack, pack.packPars(aren.allocator(), good[0 .. pack.CF.magi.len + 10])); const bad2 = try aren.allocator().dupe(u8, good); bad2[pack.CF.magi.len] = 'Z'; try std.testing.expectError(error.BadPack, pack.packPars(aren.allocator(), bad2)); try std.testing.expectError(error.BadPack, pack.packBuil(aren.allocator(), &.{.{ .hexz = "short", .gzzz = "x" }})); }
test "partOkay rejects a wrong hash and broken gzip, never crashes" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const aaaz = try gzzzOfzz(aren.allocator(), "real body"); const bbbz = try gzzzOfzz(aren.allocator(), "other body"); try std.testing.expect(pack.partOkay(aren.allocator(), aaaz.hexz, aaaz.gzzz)); try std.testing.expect(!pack.partOkay(aren.allocator(), aaaz.hexz, bbbz.gzzz)); try std.testing.expect(!pack.partOkay(aren.allocator(), aaaz.hexz, "not gzip at all")); try std.testing.expect(!pack.partOkay(aren.allocator(), "nothex", aaaz.gzzz)); }
test "names and dates: runs and keep, with and without time, unknown is null" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectEqual(@as(?i64, 1795532989000), pack.packDate("runs/20261124T150949Z-3c43.pack")); try std.testing.expectEqual(@as(?i64, 1795478400000), pack.packDate("keep/20261124-aa.pack")); try std.testing.expectEqual(@as(?i64, null), pack.packDate("runs/readme.txt")); try std.testing.expectEqual(@as(?i64, null), pack.packDate("nodate")); try std.testing.expectEqual(@as(u8, 0), pack.packGenz("runs/20261124.pack")); try std.testing.expectEqual(@as(u8, 1), pack.packGenz("keep/20261124.pack")); const nams = try pack.packName(aren.allocator(), "keep/", 1795532989000, "abc"); try std.testing.expect(std.mem.startsWith(u8, nams, "keep/20261124T150949Z-")); try std.testing.expect(std.mem.endsWith(u8, nams, ".pack")); try std.testing.expectEqual(@as(?i64, 1795532989000), pack.packDate(nams)); }
